final class TenantClient {
    private static let instances = NSMutableDictionary()
    private static let queue = DispatchQueue(label: "tenant.registry")
    let tenant: String
    private init(tenant: String) { self.tenant = tenant }

    static func forTenant(_ tenant: String) -> TenantClient {
        queue.sync {                       // lookup + insert under one lock
            let hit = instances[tenant] as? TenantClient
            let client = hit ?? TenantClient(tenant: tenant)
            instances[tenant] = client
            return client
        }
    }
}
